INSERT INTO exercises (id,name,kind,movement_pattern,difficulty,instructions,active,created_at,updated_at) VALUES
('10000000-0000-0000-0000-000000000001','Supino com halteres','STRENGTH','EMPURRAR_HORIZONTAL','BEGINNER','Ajuste o banco, mantenha os pés apoiados e execute de forma controlada.',TRUE,now(),now()),
('10000000-0000-0000-0000-000000000002','Supino com barra','STRENGTH','EMPURRAR_HORIZONTAL','INTERMEDIATE','Use as travas do rack e movimente a barra de forma controlada.',TRUE,now(),now()),
('10000000-0000-0000-0000-000000000003','Remada sentada na polia','STRENGTH','PUXAR_HORIZONTAL','BEGINNER','Mantenha o tronco estável e conduza a puxada sem impulso.',TRUE,now(),now()),
('10000000-0000-0000-0000-000000000004','Remada unilateral com halter','STRENGTH','PUXAR_HORIZONTAL','BEGINNER','Apoie-se no banco e movimente o halter de forma controlada.',TRUE,now(),now()),
('10000000-0000-0000-0000-000000000005','Leg press','STRENGTH','AGACHAR','BEGINNER','Ajuste o assento e respeite uma amplitude confortável e controlada.',TRUE,now(),now()),
('10000000-0000-0000-0000-000000000006','Agachamento goblet','STRENGTH','AGACHAR','BEGINNER','Segure um halter próximo ao tronco e mantenha estabilidade durante o movimento.',TRUE,now(),now()),
('10000000-0000-0000-0000-000000000007','Agachamento com peso corporal','STRENGTH','AGACHAR','BEGINNER','Mantenha os pés firmes e faça o movimento com controle.',TRUE,now(),now()),
('10000000-0000-0000-0000-000000000008','Levantamento romeno','STRENGTH','DOBRAR_QUADRIL','INTERMEDIATE','Mantenha a carga próxima ao corpo e controle a inclinação do tronco.',TRUE,now(),now()),
('10000000-0000-0000-0000-000000000009','Desenvolvimento com halteres','STRENGTH','EMPURRAR_VERTICAL','BEGINNER','Mantenha o tronco estável e eleve os halteres de forma controlada.',TRUE,now(),now()),
('10000000-0000-0000-0000-000000000010','Puxada alta na polia','STRENGTH','PUXAR_VERTICAL','BEGINNER','Conduza a barra em direção ao tronco sem usar impulso.',TRUE,now(),now()),
('10000000-0000-0000-0000-000000000011','Flexão de braços','STRENGTH','EMPURRAR_HORIZONTAL','BEGINNER','Mantenha o corpo alinhado e ajuste a amplitude ao seu controle.',TRUE,now(),now()),
('10000000-0000-0000-0000-000000000012','Rosca de bíceps','STRENGTH','FLEXIONAR_COTOVELO','BEGINNER','Mantenha os cotovelos estáveis e evite balanço do tronco.',TRUE,now(),now()),
('10000000-0000-0000-0000-000000000013','Extensão de tríceps na polia','STRENGTH','ESTENDER_COTOVELO','BEGINNER','Mantenha os cotovelos próximos ao corpo e controle o retorno.',TRUE,now(),now()),
('10000000-0000-0000-0000-000000000014','Elevação de panturrilhas em pé','STRENGTH','FLEXAO_PLANTAR','BEGINNER','Use apoio para equilíbrio e execute o movimento de forma controlada.',TRUE,now(),now()),
('10000000-0000-0000-0000-000000000015','Elevação pélvica com carga','STRENGTH','ESTENDER_QUADRIL','INTERMEDIATE','Apoie o tronco no banco e movimente a carga de forma estável.',TRUE,now(),now()),
('10000000-0000-0000-0000-000000000016','Barra fixa','STRENGTH','PUXAR_VERTICAL','INTERMEDIATE','Inicie com o corpo estável e realize a puxada sem balanço.',TRUE,now(),now()),
('10000000-0000-0000-0000-000000000017','Caminhada leve','WARMUP','LOCOMOCAO','BEGINNER','Caminhe em ritmo confortável para iniciar a sessão.',TRUE,now(),now()),
('10000000-0000-0000-0000-000000000018','Bicicleta leve','WARMUP','PEDALAR','BEGINNER','Ajuste o banco e pedale em ritmo confortável.',TRUE,now(),now()),
('10000000-0000-0000-0000-000000000019','Círculos de braços','WARMUP','MOBILIDADE_OMBROS','BEGINNER','Faça círculos pequenos e controlados, ampliando apenas se estiver confortável.',TRUE,now(),now()),
('10000000-0000-0000-0000-000000000020','Alongamento peitoral em pé','STRETCHING','ALONGAR_PEITORAL','BEGINNER','Posicione o braço com apoio e gire suavemente o tronco, sem forçar.',TRUE,now(),now()),
('10000000-0000-0000-0000-000000000021','Alongamento anterior de coxa','STRETCHING','ALONGAR_QUADRICEPS','BEGINNER','Use apoio para equilíbrio e aproxime o pé sem forçar a amplitude.',TRUE,now(),now()),
('10000000-0000-0000-0000-000000000022','Postura da criança','STRETCHING','ALONGAR_TRONCO','BEGINNER','Apoie-se no solo e permaneça apenas em uma posição confortável.',TRUE,now(),now());
